-- =============================================================================
-- Seed: other brands' size charts for the Ask helper (collected 2026-11-27)
-- =============================================================================
-- Re-running this updates the numbers in place (matched on brand + fit +
-- category + size). Edit later from Admin -> Ask helper -> Size charts.
-- Sources are in source_url. Bench PH and Giordano are NOT included: their
-- sites didn't load / have no single men's chart. Add them by hand if needed.
-- =============================================================================
on conflict (brand, fit, category, size) do update set
  measure_type = excluded.measure_type, chest_min_cm = excluded.chest_min_cm,
  chest_max_cm = excluded.chest_max_cm, sort_order = excluded.sort_order,
  source_url = excluded.source_url, source_note = excluded.source_note,
  checked_on = excluded.checked_on;
